pub fn decide_login(target: &LookupTarget, found: Option<AccountRow>, password: &str) -> (r: Result<IssuedClaims, LoginError>)
    ensures
        // No row found: refused as Unauthorized, the same answer as a wrong password.
        found is None ==> r == Err::<IssuedClaims, LoginError>(LoginError::Unauthorized),
        // Claims come back only for a found row whose stored hash matches the password.
        r is Ok ==> found is Some && password_matches(password@, found->Some_0.password_hash@),
        // The right password for a found row always gets claims.
        found matches Some(a) && password_matches(password@, a.password_hash@) ==> r is Ok,
        // A wrong password for a found row whose hash bcrypt can read is refused as Unauthorized.
        found matches Some(a) && bcrypt_verdict(password@, a.password_hash@) == Some(false) ==> r == Err::<IssuedClaims, LoginError>(LoginError::Unauthorized),
        // A found row whose hash bcrypt cannot read gets no claims: refused as UnreadableHash.
        found matches Some(a) && bcrypt_verdict(password@, a.password_hash@) is None ==> r matches Err(LoginError::UnreadableHash(_)),
        // The claims carry the id of the row whose password was checked.
        r matches Ok(c) ==> found is Some && c.sub@ == found->Some_0.id@,
        // An admins-table search gives the role text "admin".
        r matches Ok(c) && target is AdminByUsername ==> c.role@ == admin_role(),
        // A customers-table search gives the role text "customer".
        r matches Ok(c) && target is CustomerByEmail ==> c.role@ == customer_role(),
{
    unimplemented!()
}

