expiry_from_now.code:
pub fn expiry_from_now() -> (r: Expiry)
    ensures
        // The expiry is exactly 24 hours (86,400 seconds) after the clock reading.
        r.exp as int == r.now as int + 86_400,
{
    let now = chrono::Utc::now();
    let exp = now.checked_add_signed(chrono::Duration::hours(24)).expect("valid timestamp");
    Expiry { now: now.timestamp() as usize, exp: exp.timestamp() as usize }
}

