pub open spec fn lookup_fails(email: Option<String>, username: Option<String>) -> bool {
    match email {
        Some(e) => customer_lookup_fails(e@),
        None => match username {
            Some(u) => admin_lookup_fails(u@),
            None => false,
        },
    }
}

