        email matches Some(e) ==> r == Ok::<LookupTarget, LoginError>(LookupTarget::CustomerByEmail(e)),
        // With no email, a username sends the search to admins for exactly that username.
        email is None && username matches Some(u) ==> r == Ok::<LookupTarget, LoginError>(LookupTarget::AdminByUsername(u)),
        // With neither, the login is refused for missing an identity.
        email is None && username is None ==> r == Err::<LookupTarget, LoginError>(LoginError::MissingIdentity),
